    (select min(bc) from bb where rc=x->>0 and q=1), (select min(bc) from bb where rc=x->>0 and q>1),
    (x->>3)::int, x->>0, 'Acrescentado do catálogo Repsol de Penafiel (01/11/2026)'
  from d, cat, jsonb_array_elements(d.j->'p') x
  where not exists(select 1 from products q where q.repsol_code=x->>0 or q.id='r'||(x->>0))
  returning id, repsol_code),
nb as (
  insert into public.product_barcodes(barcode,product_id,qty)
  select distinct on (bb.bc) bb.bc, np.id, bb.q from bb join np on np.repsol_code=bb.rc
  on conflict do nothing returning barcode)
select (select count(*) from np) produtos, (select count(*) from nb) codigos;